"""A rich month must reach the merchant listing so its own plan can run.

#4988 moved the BARGAIN_TARGETS provisional pass behind ``not rich``. Without a
listing the provisional pass then planned nothing, ``shop['items']`` stayed
empty and flows/month.py recorded ``month_merchant_skipped``; the month never
opened the merchant, so the listing pass that owns the rich visit never ran and
a rich month (1000G+) bought no card at all (prod g1190 9883G, local run16
9999G). The fix adds one tentative row per known, short kind only to reach the
listing; the listing pass replaces those rows with the observed prices.

All screens/gold/stock here are synthetic, not observed live data.
"""
from docich.hanjuku_speedrun import hanjuku_policy as p
from docich.hanjuku_speedrun.hanjuku.strategy import bargains as b
from docich.hanjuku_speedrun.hanjuku_bot import decide
from .test_hanjuku_chart_bot import month_canvas

TARGETS = sorted(set(b.RICH_MERCHANT_CARDS) | set(b.BARGAIN_TARGETS))


def memory(stock, gold=9999, month=3):
    # The bounded monthly roster scan is already spent; this test is the
    # merchant decision, not the count visit (matching the other month tests).
    return {'chapter': 9, 'month': f'1-{month}', 'tick': 1, 'egg_uses': {},
            'card_stock': dict(stock), 'soldiers_seen': 100,
            'soldiers_seen_key': f'1-{month}', 'orders': {}, 'picked': [],
            'recruit_month_scan_attempts': {'scope': [9, f'1-{month}'], 'count': 2}}


def decisions(state):
    return [row['decision'] for row in state.get('_records', ())]


def test_rich_month_with_a_known_short_target_opens_the_merchant():
    stock = {'ノリウツール': 0, 'ミックミー': 0, 'イッテツーン': 0}
    actions, state = decide(month_canvas(9999, on='しょうにん', month=3),
                            {'policy': memory(stock)})
    shop = state['policy']['shop']
    assert shop['rich_merchant'] is True
    assert shop['items'] and shop['merchant_done'] is False
    assert {name for name, _ in shop['items']} == set(stock)
    assert all(0 < qty <= b.HOLD_CAP for _, qty in shop['items'])
    assert 'month_merchant_skipped' not in decisions(state)
    # The month menu heading for しょうにん presses A to enter the merchant.
    assert actions == [p.pad('a')]
    assert state['policy'].get('month_merchant_confirm') is True


def test_rich_month_with_every_known_target_at_99_skips_the_merchant():
    stock = {name: 99 for name in TARGETS}
    actions, state = decide(month_canvas(9999, on='しょうにん', month=3),
                            {'policy': memory(stock)})
    shop = state['policy']['shop']
    assert shop['items'] == [] and shop['merchant_done'] is True
    assert 'month_merchant_skipped' in decisions(state)
    assert actions != [p.pad('a')]


def test_rich_month_with_an_unknown_ledger_plans_nothing():
    # A missing key is unknown, never 0: the full-inventory read fills it.
    _, state = decide(month_canvas(9999, on='しょうにん', month=3),
                      {'policy': memory({})})
    shop = state['policy']['shop']
    assert shop['items'] == [] and shop['merchant_done'] is True
    assert 'month_merchant_skipped' in decisions(state)


def test_the_listing_pass_replaces_the_provisional_rows():
    mem = memory({'ノリウツール': 98, 'ミックミー': 0, 'イッテツーン': 0, 'グリンボー': 99})
    header = {'year': 1, 'month': 3, 'gold': 9999}
    shop = p._plan(mem, header)
    provisional = dict(shop['items'])
    assert set(provisional) == {'ノリウツール', 'ミックミー', 'イッテツーン'}
    assert shop['bargain_cards'] == [name for name, _ in shop['items']]
    # The listing sells only ミックミー; グリンボー is listed at 99 held.
    assert b.plan_bargains(mem, shop, header,
                           listed={'ミックミー': 40, 'グリンボー': 6}) is shop
    assert [name for name, _ in shop['items']] == ['ミックミー']
    assert shop['bargain_cards'] == ['ミックミー']
    # The replaced provisional rows and the full kind are not asked again.
    assert {'ノリウツール', 'イッテツーン', 'グリンボー'}.isdisjoint(dict(shop['items']))


def test_unpriced_requested_cards_wait_for_a_readable_listing():
    # フットバース/ピッグローラー carry only an acceptance ceiling, not a shop
    # price: no provisional row is invented for them.
    mem = memory({'フットバース': 0, 'ピッグローラー': 0, 'ノリウツール': 0})
    shop = p._plan(mem, {'year': 1, 'month': 3, 'gold': 9999})
    assert set(dict(shop['items'])) == {'ノリウツール'}
    header = {'year': 1, 'month': 3, 'gold': 9999}
    b.plan_bargains(mem, shop, header, listed={'フットバース': 15, 'ピッグローラー': 12})
    chosen = dict(shop['items'])
    assert chosen.get('フットバース', 0) > 0 and chosen.get('ピッグローラー', 0) > 0
